-- >>>>>>>>>> 0001_schema.sql <<<<<<<<<<
-- Elevate Campus Hub — 0001 schema
-- Tables, constraints, indexes and triggers. RLS policies live in 0002.

-- ---------------------------------------------------------------------------
-- campuses
-- ---------------------------------------------------------------------------
create table public.campuses (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  -- Attendance dates are computed in the campus timezone (the DB runs in UTC).
  timezone text not null default 'Asia/Manila',
  target_google_doc_id text,
  google_form_webhook_url text,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- programs (campus_id null = global, available to every campus)
-- ---------------------------------------------------------------------------
create table public.programs (
  id uuid primary key default gen_random_uuid(),
  campus_id uuid references public.campuses (id) on delete cascade,
  code text not null,
  name text not null,
  is_active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

create unique index programs_code_unique
  on public.programs (coalesce(campus_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(code));

-- ---------------------------------------------------------------------------
-- profiles (1:1 with auth.users)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  campus_id uuid references public.campuses (id),
  role text not null check (role in ('super_admin', 'campus_head', 'facilitator', 'student')),
  first_name text not null,
  last_name text not null,
  email text not null,
  phone text,
  gender text check (gender in ('male', 'female')),
  birthday date,
  church text,
  religion text,
  program_id uuid references public.programs (id),
  year_level int check (year_level between 1 and 10),
  student_number text,
  qr_token text unique,
  is_active boolean not null default true,
  password_changed boolean not null default false,
  invitation_sent_at timestamptz,
  invitation_accepted_at timestamptz,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  -- Only the Super Admin is global; everyone else belongs to a campus.
  constraint profiles_campus_required check (role = 'super_admin' or campus_id is not null),
  -- Gender drives same-gender chat, so it is mandatory for chat participants.
  constraint profiles_gender_required check (role not in ('student', 'facilitator') or gender is not null)
);

create unique index profiles_email_unique on public.profiles (lower(email));
create unique index profiles_phone_per_campus on public.profiles (campus_id, phone) where phone is not null;
create index profiles_campus_role_idx on public.profiles (campus_id, role);

-- Every student gets a unique QR token automatically.
create or replace function public.profiles_set_qr_token()
returns trigger
language plpgsql
as $$
begin
  if new.role = 'student' and new.qr_token is null then
    new.qr_token := gen_random_uuid()::text;
  end if;
  return new;
end;
$$;

create trigger profiles_set_qr_token
  before insert on public.profiles
  for each row execute function public.profiles_set_qr_token();

-- ---------------------------------------------------------------------------
-- facilitator_students (a student has at most one ACTIVE facilitator)
-- ---------------------------------------------------------------------------
create table public.facilitator_students (
  id uuid primary key default gen_random_uuid(),
  facilitator_id uuid not null references public.profiles (id) on delete cascade,
  student_id uuid not null references public.profiles (id) on delete cascade,
  campus_id uuid not null references public.campuses (id),
  assigned_date date not null default current_date,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create unique index facilitator_students_one_active_per_student
  on public.facilitator_students (student_id) where is_active;
create index facilitator_students_facilitator_idx on public.facilitator_students (facilitator_id) where is_active;

-- ---------------------------------------------------------------------------
-- facilitator_availability
-- ---------------------------------------------------------------------------
create table public.facilitator_availability (
  id uuid primary key default gen_random_uuid(),
  facilitator_id uuid not null references public.profiles (id) on delete cascade,
  day_of_week int not null check (day_of_week between 0 and 6), -- 0 = Sunday
  start_time time not null,
  end_time time not null,
  is_available boolean not null default true,
  created_at timestamptz not null default now(),
  constraint availability_time_order check (end_time > start_time)
);

create index facilitator_availability_facilitator_idx
  on public.facilitator_availability (facilitator_id, day_of_week);

-- ---------------------------------------------------------------------------
-- attendance_logs (one row per student per campus-local day)
-- ---------------------------------------------------------------------------
create table public.attendance_logs (
  id uuid primary key default gen_random_uuid(),
  campus_id uuid not null references public.campuses (id),
  student_id uuid not null references public.profiles (id) on delete cascade,
  log_date date not null,
  time_in timestamptz not null default now(),
  time_out timestamptz,
  purpose text,
  scanned_by uuid not null references public.profiles (id),
  entry_method text not null check (entry_method in ('qr', 'phone', 'email', 'manual')),
  created_at timestamptz not null default now(),
  constraint attendance_one_per_day unique (student_id, log_date)
);

create index attendance_logs_campus_date_idx on public.attendance_logs (campus_id, log_date);

-- ---------------------------------------------------------------------------
-- engagement_logs (0..1 per attendance log)
-- ---------------------------------------------------------------------------
create table public.engagement_logs (
  id uuid primary key default gen_random_uuid(),
  attendance_log_id uuid not null unique references public.attendance_logs (id) on delete cascade,
  student_id uuid not null references public.profiles (id) on delete cascade,
  facilitator_id uuid not null references public.profiles (id),
  campus_id uuid not null references public.campuses (id),
  is_engaged boolean not null default false,
  heard_gospel boolean not null default false,
  accepted_jesus boolean not null default false,
  wants_dgroup boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index engagement_logs_campus_idx on public.engagement_logs (campus_id);

-- ---------------------------------------------------------------------------
-- daily_reports
-- ---------------------------------------------------------------------------
create table public.daily_reports (
  id uuid primary key default gen_random_uuid(),
  campus_id uuid not null references public.campuses (id),
  report_date date not null,
  total_attendance int not null default 0,
  students_engaged int not null default 0,
  students_heard_gospel int not null default 0,
  students_accepted_jesus int not null default 0,
  students_wants_dgroup int not null default 0,
  volunteers_count int not null default 0,
  notes text,
  submitted_by uuid not null references public.profiles (id),
  is_locked boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint daily_reports_one_per_day unique (campus_id, report_date)
);

-- ---------------------------------------------------------------------------
-- report_submissions (history of pushes to Google Docs / Forms)
-- ---------------------------------------------------------------------------
create table public.report_submissions (
  id uuid primary key default gen_random_uuid(),
  campus_id uuid not null references public.campuses (id),
  report_title text not null,
  date_from date not null,
  date_to date not null,
  total_attendees int not null default 0,
  target_google_doc_url text,
  target_google_form_url text,
  submission_type text not null check (submission_type in ('google_docs', 'google_form')),
  status text not null default 'pending' check (status in ('pending', 'submitted', 'failed')),
  payload jsonb,
  submitted_by uuid not null references public.profiles (id),
  submitted_at timestamptz not null default now()
);

create index report_submissions_campus_idx on public.report_submissions (campus_id, submitted_at desc);

-- ---------------------------------------------------------------------------
-- chat_messages
-- ---------------------------------------------------------------------------
create table public.chat_messages (
  id uuid primary key default gen_random_uuid(),
  sender_id uuid not null references public.profiles (id) on delete cascade,
  receiver_id uuid not null references public.profiles (id) on delete cascade,
  campus_id uuid not null references public.campuses (id),
  message text not null check (char_length(message) between 1 and 2000),
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);

create index chat_messages_pair_idx on public.chat_messages (sender_id, receiver_id, created_at);
create index chat_messages_receiver_unread_idx on public.chat_messages (receiver_id) where not is_read;

-- ---------------------------------------------------------------------------
-- system_logs (11th table: Super Admin log viewer + keep-alive status)
-- ---------------------------------------------------------------------------
create table public.system_logs (
  id uuid primary key default gen_random_uuid(),
  event text not null,
  level text not null default 'info' check (level in ('info', 'warn', 'error')),
  detail jsonb,
  created_at timestamptz not null default now()
);

create index system_logs_created_idx on public.system_logs (created_at desc);

-- ---------------------------------------------------------------------------
-- updated_at maintenance + locked-report guard
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger engagement_logs_updated_at
  before update on public.engagement_logs
  for each row execute function public.set_updated_at();

create trigger daily_reports_updated_at
  before update on public.daily_reports
  for each row execute function public.set_updated_at();

-- A locked report cannot be edited. Unlocking (locked -> unlocked) is allowed.
create or replace function public.daily_reports_guard_locked()
returns trigger
language plpgsql
as $$
begin
  if old.is_locked and new.is_locked then
    raise exception 'This daily report is locked. Unlock it before editing.' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create trigger daily_reports_guard_locked
  before update on public.daily_reports
  for each row execute function public.daily_reports_guard_locked();

-- >>>>>>>>>> 0002_rls.sql <<<<<<<<<<
-- Elevate Campus Hub — 0002 row level security
--
-- Model:
--   * Every table has RLS enabled (default deny).
--   * Reads/ordinary writes go through the signed-in user's session and are limited here.
--   * Account creation / password resets / cron / webhook logging use the service-role key
--     on the server (it bypasses RLS) after the server action checked the caller's role.
--   * Attendance is written only through public.toggle_attendance() (0003).

-- ---------------------------------------------------------------------------
-- Helper functions (SECURITY DEFINER so policies on profiles cannot recurse)
-- ---------------------------------------------------------------------------
create or replace function public.auth_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role from public.profiles where id = auth.uid() and is_active
$$;

create or replace function public.auth_campus_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select campus_id from public.profiles where id = auth.uid() and is_active
$$;

create or replace function public.campus_of(p_user uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select campus_id from public.profiles where id = p_user
$$;

-- Same-gender chat rule: an active facilitator<->student assignment exists, both are
-- active, in the same campus, with the same gender.
create or replace function public.can_chat(p_a uuid, p_b uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.facilitator_students fs
    join public.profiles f on f.id = fs.facilitator_id
    join public.profiles s on s.id = fs.student_id
    where fs.is_active
      and f.is_active and s.is_active
      and f.role = 'facilitator' and s.role = 'student'
      and f.gender is not null and f.gender = s.gender
      and f.campus_id = s.campus_id
      and ((fs.facilitator_id = p_a and fs.student_id = p_b)
        or (fs.facilitator_id = p_b and fs.student_id = p_a))
  )
$$;

-- ---------------------------------------------------------------------------
-- Enable RLS everywhere
-- ---------------------------------------------------------------------------
alter table public.campuses enable row level security;
alter table public.programs enable row level security;
alter table public.profiles enable row level security;
alter table public.facilitator_students enable row level security;
alter table public.facilitator_availability enable row level security;
alter table public.attendance_logs enable row level security;
alter table public.engagement_logs enable row level security;
alter table public.daily_reports enable row level security;
alter table public.report_submissions enable row level security;
alter table public.chat_messages enable row level security;
alter table public.system_logs enable row level security;

-- ---------------------------------------------------------------------------
-- campuses: Super Admin full; everyone else reads own campus
-- ---------------------------------------------------------------------------
create policy campuses_select on public.campuses for select to authenticated
  using (public.auth_role() = 'super_admin' or id = public.auth_campus_id());

create policy campuses_admin_write on public.campuses for all to authenticated
  using (public.auth_role() = 'super_admin')
  with check (public.auth_role() = 'super_admin');

-- ---------------------------------------------------------------------------
-- programs: Super Admin full; others read global + own campus programs
-- ---------------------------------------------------------------------------
create policy programs_select on public.programs for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() is not null and (campus_id is null or campus_id = public.auth_campus_id()))
  );

create policy programs_admin_write on public.programs for all to authenticated
  using (public.auth_role() = 'super_admin')
  with check (public.auth_role() = 'super_admin');

-- ---------------------------------------------------------------------------
-- profiles: read-only through RLS. All profile writes go through server actions
-- that use the service-role key after checking the caller's role.
-- ---------------------------------------------------------------------------
create policy profiles_select on public.profiles for select to authenticated
  using (
    id = auth.uid()
    or public.auth_role() = 'super_admin'
    -- Campus Head sees everyone in the campus; facilitators see the campus's students.
    or (
      campus_id = public.auth_campus_id()
      and (
        public.auth_role() = 'campus_head'
        or (public.auth_role() = 'facilitator' and role = 'student')
      )
    )
    -- A student sees their assigned facilitator.
    or id in (
      select fs.facilitator_id from public.facilitator_students fs
      where fs.student_id = auth.uid() and fs.is_active
    )
  );

-- ---------------------------------------------------------------------------
-- facilitator_students
-- ---------------------------------------------------------------------------
create policy fs_select on public.facilitator_students for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
    or facilitator_id = auth.uid()
    or student_id = auth.uid()
  );

create policy fs_campus_head_write on public.facilitator_students for all to authenticated
  using (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  with check (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id());

-- ---------------------------------------------------------------------------
-- facilitator_availability
-- ---------------------------------------------------------------------------
create policy availability_select on public.facilitator_availability for select to authenticated
  using (
    facilitator_id = auth.uid()
    or public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and public.campus_of(facilitator_id) = public.auth_campus_id())
    or facilitator_id in (
      select fs.facilitator_id from public.facilitator_students fs
      where fs.student_id = auth.uid() and fs.is_active
    )
  );

-- Facilitators and Campus Heads manage their own weekly schedule.
create policy availability_own_write on public.facilitator_availability for all to authenticated
  using (facilitator_id = auth.uid() and public.auth_role() in ('facilitator', 'campus_head'))
  with check (facilitator_id = auth.uid() and public.auth_role() in ('facilitator', 'campus_head'));

-- ---------------------------------------------------------------------------
-- attendance_logs: read only; writes via toggle_attendance()
-- ---------------------------------------------------------------------------
create policy attendance_select on public.attendance_logs for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() in ('campus_head', 'facilitator') and campus_id = public.auth_campus_id())
    or student_id = auth.uid()
  );

-- ---------------------------------------------------------------------------
-- engagement_logs: Campus Head + facilitators of the campus. Students never see these.
-- ---------------------------------------------------------------------------
create policy engagement_select on public.engagement_logs for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() in ('campus_head', 'facilitator') and campus_id = public.auth_campus_id())
  );

create policy engagement_insert on public.engagement_logs for insert to authenticated
  with check (
    public.auth_role() in ('campus_head', 'facilitator')
    and campus_id = public.auth_campus_id()
    and facilitator_id = auth.uid()
    and exists (
      select 1 from public.attendance_logs a
      where a.id = attendance_log_id
        and a.student_id = engagement_logs.student_id
        and a.campus_id = engagement_logs.campus_id
    )
  );

create policy engagement_update on public.engagement_logs for update to authenticated
  using (
    public.auth_role() in ('campus_head', 'facilitator')
    and campus_id = public.auth_campus_id()
  )
  with check (
    public.auth_role() in ('campus_head', 'facilitator')
    and campus_id = public.auth_campus_id()
    and facilitator_id = auth.uid()
  );

-- ---------------------------------------------------------------------------
-- daily_reports: Campus Head full for own campus; Super Admin read-only
-- ---------------------------------------------------------------------------
create policy daily_reports_select on public.daily_reports for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  );

create policy daily_reports_campus_head_write on public.daily_reports for all to authenticated
  using (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  with check (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id());

-- ---------------------------------------------------------------------------
-- report_submissions
-- ---------------------------------------------------------------------------
create policy submissions_select on public.report_submissions for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  );

create policy submissions_campus_head_write on public.report_submissions for all to authenticated
  using (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  with check (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id());

-- ---------------------------------------------------------------------------
-- chat_messages: strictly same-gender, assigned facilitator <-> student
-- ---------------------------------------------------------------------------
create policy chat_select on public.chat_messages for select to authenticated
  using (sender_id = auth.uid() or receiver_id = auth.uid());

create policy chat_insert on public.chat_messages for insert to authenticated
  with check (
    sender_id = auth.uid()
    and campus_id = public.auth_campus_id()
    and public.can_chat(sender_id, receiver_id)
  );

create policy chat_mark_read on public.chat_messages for update to authenticated
  using (receiver_id = auth.uid())
  with check (receiver_id = auth.uid());

-- The receiver may only flip is_read; the message text is immutable.
revoke update on public.chat_messages from authenticated, anon;
grant update (is_read) on public.chat_messages to authenticated;
revoke delete on public.chat_messages from authenticated, anon;

-- ---------------------------------------------------------------------------
-- system_logs: Super Admin read-only (the server writes with the service-role key)
-- ---------------------------------------------------------------------------
create policy system_logs_select on public.system_logs for select to authenticated
  using (public.auth_role() = 'super_admin');

-- ---------------------------------------------------------------------------
-- Realtime: stream new chat messages (RLS still applies to subscribers)
-- ---------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'chat_messages'
     ) then
    alter publication supabase_realtime add table public.chat_messages;
  end if;
end;
$$;

-- >>>>>>>>>> 0003_functions.sql <<<<<<<<<<
-- Elevate Campus Hub — 0003 business-logic functions

-- ---------------------------------------------------------------------------
-- toggle_attendance
--   Scan #1 of the campus-local day -> time_in
--   Scan #2                         -> time_out
--   Scan #3+                        -> 'already_completed' (nothing changes)
--   Also auto-assigns the student to the scanning facilitator when the student has
--   no active facilitator yet (Campus Head scans never assign).
-- ---------------------------------------------------------------------------
create or replace function public.toggle_attendance(
  p_student_id uuid,
  p_method text default 'qr',
  p_purpose text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller public.profiles%rowtype;
  v_student public.profiles%rowtype;
  v_tz text;
  v_today date;
  v_log public.attendance_logs%rowtype;
  v_action text;
  v_assigned boolean := false;
  v_fac_id uuid;
  v_fac_gender text;
begin
  select * into v_caller from public.profiles where id = auth.uid() and is_active;
  if not found or v_caller.role not in ('campus_head', 'facilitator') then
    raise exception 'Only a Campus Head or Facilitator can mark attendance.' using errcode = '42501';
  end if;

  if p_method not in ('qr', 'phone', 'email', 'manual') then
    raise exception 'Invalid entry method: %', p_method using errcode = '22023';
  end if;

  select * into v_student
  from public.profiles
  where id = p_student_id and role = 'student' and is_active;
  if not found or v_student.campus_id is distinct from v_caller.campus_id then
    raise exception 'Student not found in your campus.' using errcode = 'P0002';
  end if;

  select coalesce(timezone, 'Asia/Manila') into v_tz from public.campuses where id = v_caller.campus_id;
  v_today := (now() at time zone coalesce(v_tz, 'Asia/Manila'))::date;

  insert into public.attendance_logs (campus_id, student_id, log_date, time_in, purpose, scanned_by, entry_method)
  values (v_caller.campus_id, p_student_id, v_today, now(), p_purpose, v_caller.id, p_method)
  on conflict (student_id, log_date) do nothing
  returning * into v_log;

  if found then
    v_action := 'time_in';
  else
    select * into v_log
    from public.attendance_logs
    where student_id = p_student_id and log_date = v_today
    for update;

    if v_log.time_out is null then
      update public.attendance_logs set time_out = now() where id = v_log.id returning * into v_log;
      v_action := 'time_out';
    else
      v_action := 'already_completed';
    end if;
  end if;

  -- Auto-assignment: first facilitator to take the student's attendance becomes their facilitator.
  if v_caller.role = 'facilitator'
     and not exists (
       select 1 from public.facilitator_students where student_id = p_student_id and is_active
     ) then
    insert into public.facilitator_students (facilitator_id, student_id, campus_id, assigned_date)
    values (v_caller.id, p_student_id, v_caller.campus_id, v_today)
    on conflict do nothing;
    v_assigned := true;
  end if;

  select fs.facilitator_id, f.gender into v_fac_id, v_fac_gender
  from public.facilitator_students fs
  join public.profiles f on f.id = fs.facilitator_id
  where fs.student_id = p_student_id and fs.is_active;

  return jsonb_build_object(
    'action', v_action,
    'assigned_now', v_assigned,
    'facilitator_id', v_fac_id,
    'gender_mismatch', (v_fac_id is not null and v_fac_gender is distinct from v_student.gender),
    'log', jsonb_build_object(
      'id', v_log.id,
      'log_date', v_log.log_date,
      'time_in', v_log.time_in,
      'time_out', v_log.time_out,
      'entry_method', v_log.entry_method
    ),
    'student', jsonb_build_object(
      'id', v_student.id,
      'first_name', v_student.first_name,
      'last_name', v_student.last_name,
      'phone', v_student.phone,
      'email', v_student.email
    )
  );
end;
$$;

revoke execute on function public.toggle_attendance(uuid, text, text) from public, anon;
grant execute on function public.toggle_attendance(uuid, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- compute_daily_report — the spec's section 5.4 auto-calculations.
-- SECURITY INVOKER: RLS applies, so a Campus Head only ever aggregates their own campus.
-- ---------------------------------------------------------------------------
create or replace function public.compute_daily_report(p_campus_id uuid, p_date date)
returns table (
  total_attendance int,
  students_engaged int,
  students_heard_gospel int,
  students_accepted_jesus int,
  students_wants_dgroup int,
  volunteers_count int
)
language sql
stable
as $$
  select
    (select count(distinct a.student_id)::int
       from public.attendance_logs a
      where a.campus_id = p_campus_id and a.log_date = p_date),
    (select count(distinct e.student_id)::int
       from public.engagement_logs e
       join public.attendance_logs a on a.id = e.attendance_log_id
      where a.campus_id = p_campus_id and a.log_date = p_date and e.is_engaged),
    (select count(distinct e.student_id)::int
       from public.engagement_logs e
       join public.attendance_logs a on a.id = e.attendance_log_id
      where a.campus_id = p_campus_id and a.log_date = p_date and e.heard_gospel),
    (select count(distinct e.student_id)::int
       from public.engagement_logs e
       join public.attendance_logs a on a.id = e.attendance_log_id
      where a.campus_id = p_campus_id and a.log_date = p_date and e.accepted_jesus),
    (select count(distinct e.student_id)::int
       from public.engagement_logs e
       join public.attendance_logs a on a.id = e.attendance_log_id
      where a.campus_id = p_campus_id and a.log_date = p_date and e.wants_dgroup),
    (select count(distinct a.scanned_by)::int
       from public.attendance_logs a
       join public.profiles p on p.id = a.scanned_by
      where a.campus_id = p_campus_id and a.log_date = p_date and p.role = 'facilitator')
$$;

-- ---------------------------------------------------------------------------
-- range_report_summary — totals for a date range, used for Google submissions.
-- Student figures are the sum of the saved daily reports (so Campus Head edits count);
-- volunteers are the DISTINCT facilitators across the whole range.
-- ---------------------------------------------------------------------------
create or replace function public.range_report_summary(p_campus_id uuid, p_from date, p_to date)
returns table (
  days_with_report int,
  total_attendance int,
  students_engaged int,
  students_heard_gospel int,
  students_accepted_jesus int,
  students_wants_dgroup int,
  volunteers_count int
)
language sql
stable
as $$
  select
    count(*)::int,
    coalesce(sum(d.total_attendance), 0)::int,
    coalesce(sum(d.students_engaged), 0)::int,
    coalesce(sum(d.students_heard_gospel), 0)::int,
    coalesce(sum(d.students_accepted_jesus), 0)::int,
    coalesce(sum(d.students_wants_dgroup), 0)::int,
    (select count(distinct a.scanned_by)::int
       from public.attendance_logs a
       join public.profiles p on p.id = a.scanned_by
      where a.campus_id = p_campus_id
        and a.log_date between p_from and p_to
        and p.role = 'facilitator')
  from public.daily_reports d
  where d.campus_id = p_campus_id and d.report_date between p_from and p_to
$$;

