on conflict do nothing;

-- >>>>>>>>>> 0005_batches.sql <<<<<<<<<<
-- Elevate Campus Hub — 0005 engagement batches (huddles)
--
-- New flow: a facilitator (or Campus Head) STARTS A BATCH, adds students to it (that is now how
-- attendance is recorded), records each student's engagement, then FINISHES the batch, which
-- moves it to History. Run this on top of 0001-0004 (the Supabase SQL Editor is fine).
--
-- Time semantics change: attendance_logs.time_in = when the student was added to the batch;
-- time_out = when the facilitator finished recording their engagement (how long the engagement took),
-- no longer "left the hub". The old scan-in/scan-out function is removed.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
create table public.engagement_batches (
  id uuid primary key default gen_random_uuid(),
  campus_id uuid not null references public.campuses (id),
  facilitator_id uuid not null references public.profiles (id),
  batch_date date not null,                 -- campus-local day the batch was started
  batch_number int not null check (batch_number > 0),
  status text not null default 'open' check (status in ('open', 'finished')),
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  created_at timestamptz not null default now(),
  constraint batches_number_unique unique (facilitator_id, batch_date, batch_number),
  constraint batches_finished_has_time check (status = 'open' or finished_at is not null)
);

create index engagement_batches_campus_date_idx on public.engagement_batches (campus_id, batch_date, status);
create index engagement_batches_open_idx on public.engagement_batches (facilitator_id) where status = 'open';

create table public.batch_students (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.engagement_batches (id) on delete cascade,
  student_id uuid not null references public.profiles (id) on delete cascade,
  attendance_log_id uuid not null references public.attendance_logs (id) on delete cascade,
  campus_id uuid not null references public.campuses (id),
  added_at timestamptz not null default now(),
  constraint batch_students_unique unique (batch_id, student_id)
);

-- A student is huddled in at most ONE batch per day (their attendance row is per day).
create unique index batch_students_one_batch_per_day on public.batch_students (attendance_log_id);
create index batch_students_batch_idx on public.batch_students (batch_id);

-- ---------------------------------------------------------------------------
-- Row level security: read-only from the app; every write goes through the functions below
-- ---------------------------------------------------------------------------
alter table public.engagement_batches enable row level security;
alter table public.batch_students enable row level security;

create or replace function public.is_batch_owner(p_batch uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.engagement_batches b where b.id = p_batch and b.facilitator_id = auth.uid()
  )
$$;

create policy batches_select on public.engagement_batches for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
    or facilitator_id = auth.uid()
  );

create policy batch_students_select on public.batch_students for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
    or public.is_batch_owner(batch_id)
  );

-- Engagement is now written only through save_engagement() (it must belong to an open batch you own).
drop policy if exists engagement_insert on public.engagement_logs;
drop policy if exists engagement_update on public.engagement_logs;

-- The old scan-in / scan-out toggle is replaced by add_student_to_batch().
drop function if exists public.toggle_attendance(uuid, text, text);

-- ---------------------------------------------------------------------------
-- start_batch(): opens the next batch number for today
-- ---------------------------------------------------------------------------
create or replace function public.start_batch()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller public.profiles%rowtype;
  v_tz text;
  v_today date;
  v_number int;
  v_batch public.engagement_batches%rowtype;
begin
  select * into v_caller from public.profiles where id = auth.uid() and is_active;
  if not found or v_caller.role not in ('campus_head', 'facilitator') then
    raise exception 'Only a Campus Head or Facilitator can start a batch.' using errcode = '42501';
  end if;

  select coalesce(timezone, 'Asia/Manila') into v_tz from public.campuses where id = v_caller.campus_id;
  v_today := (now() at time zone coalesce(v_tz, 'Asia/Manila'))::date;

  select coalesce(max(batch_number), 0) + 1 into v_number
  from public.engagement_batches
  where facilitator_id = v_caller.id and batch_date = v_today;

  insert into public.engagement_batches (campus_id, facilitator_id, batch_date, batch_number)
  values (v_caller.campus_id, v_caller.id, v_today, v_number)
  returning * into v_batch;

  return jsonb_build_object(
    'id', v_batch.id,
    'batch_number', v_batch.batch_number,
    'batch_date', v_batch.batch_date,
    'started_at', v_batch.started_at
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- add_student_to_batch(): the new "attendance". Creates today's attendance row if needed,
-- links the student to the batch, and auto-assigns them to the facilitator when unassigned.
-- ---------------------------------------------------------------------------
create or replace function public.add_student_to_batch(
  p_batch_id uuid,
  p_student_id uuid,
  p_method text default 'manual'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller public.profiles%rowtype;
  v_batch public.engagement_batches%rowtype;
  v_student public.profiles%rowtype;
  v_log public.attendance_logs%rowtype;
  v_link public.batch_students%rowtype;
  v_other_batch public.engagement_batches%rowtype;
  v_other_name text;
  v_action text;
  v_assigned boolean := false;
  v_fac_id uuid;
  v_fac_gender text;
begin
  select * into v_caller from public.profiles where id = auth.uid() and is_active;
  if not found or v_caller.role not in ('campus_head', 'facilitator') then
    raise exception 'Only a Campus Head or Facilitator can add students to a batch.' using errcode = '42501';
  end if;

  select * into v_batch from public.engagement_batches where id = p_batch_id;
  if not found or v_batch.facilitator_id <> v_caller.id then
    raise exception 'That batch isn''t yours.' using errcode = '42501';
  end if;
  if v_batch.status <> 'open' then
    raise exception 'This batch is already finished.' using errcode = 'P0001';
  end if;

  if p_method not in ('qr', 'phone', 'email', 'manual') then
    raise exception 'Invalid entry method: %', p_method using errcode = '22023';
  end if;

  select * into v_student
  from public.profiles
  where id = p_student_id and role = 'student' and is_active;
  if not found or v_student.campus_id is distinct from v_caller.campus_id then
    raise exception 'Student not found in your campus.' using errcode = 'P0002';
  end if;

  -- Attendance for the batch's day (one row per student per day).
  insert into public.attendance_logs (campus_id, student_id, log_date, time_in, scanned_by, entry_method)
  values (v_caller.campus_id, p_student_id, v_batch.batch_date, now(), v_caller.id, p_method)
  on conflict (student_id, log_date) do nothing
  returning * into v_log;

  if not found then
    select * into v_log from public.attendance_logs
    where student_id = p_student_id and log_date = v_batch.batch_date;
  end if;

  select * into v_link from public.batch_students where attendance_log_id = v_log.id;
  if found then
    if v_link.batch_id = p_batch_id then
      v_action := 'already_in_batch';
    else
      select * into v_other_batch from public.engagement_batches where id = v_link.batch_id;
      select first_name into v_other_name from public.profiles where id = v_other_batch.facilitator_id;
      raise exception '% is already in % Batch % today.',
        v_student.first_name,
        case when v_other_batch.facilitator_id = v_caller.id then 'your' else coalesce(v_other_name, 'another facilitator') || '''s' end,
        v_other_batch.batch_number
        using errcode = 'P0001';
    end if;
  else
    insert into public.batch_students (batch_id, student_id, attendance_log_id, campus_id)
    values (p_batch_id, p_student_id, v_log.id, v_caller.campus_id);
    v_action := 'added';
  end if;

  -- First facilitator to huddle an unassigned student becomes their facilitator (Campus Head never assigns).
  if v_caller.role = 'facilitator'
     and not exists (select 1 from public.facilitator_students where student_id = p_student_id and is_active) then
    insert into public.facilitator_students (facilitator_id, student_id, campus_id, assigned_date)
    values (v_caller.id, p_student_id, v_caller.campus_id, v_batch.batch_date)
    on conflict do nothing;
    v_assigned := true;
  end if;

  select fs.facilitator_id, f.gender into v_fac_id, v_fac_gender
  from public.facilitator_students fs
  join public.profiles f on f.id = fs.facilitator_id
  where fs.student_id = p_student_id and fs.is_active;

  return jsonb_build_object(
    'action', v_action,
    'batch_number', v_batch.batch_number,
    'assigned_now', v_assigned,
    'facilitator_id', v_fac_id,
    'gender_mismatch', (v_fac_id is not null and v_fac_gender is distinct from v_student.gender),
    'log', jsonb_build_object('id', v_log.id, 'time_in', v_log.time_in, 'time_out', v_log.time_out),
    'student', jsonb_build_object(
      'id', v_student.id,
      'first_name', v_student.first_name,
      'last_name', v_student.last_name,
      'phone', v_student.phone,
      'email', v_student.email
    )
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- save_engagement(): the 4-question assessment. Only the batch's own facilitator, only while the
-- batch is open. Saving also ends the "engaged for" timer for that student (attendance time_out).
-- ---------------------------------------------------------------------------
create or replace function public.save_engagement(
  p_attendance_log_id uuid,
  p_is_engaged boolean,
  p_heard_gospel boolean,
  p_accepted_jesus boolean,
  p_wants_dgroup boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller public.profiles%rowtype;
  v_batch public.engagement_batches%rowtype;
  v_log public.attendance_logs%rowtype;
begin
  select * into v_caller from public.profiles where id = auth.uid() and is_active;
  if not found or v_caller.role not in ('campus_head', 'facilitator') then
    raise exception 'Only a Campus Head or Facilitator can record engagement.' using errcode = '42501';
  end if;

  select b.* into v_batch
  from public.batch_students bs
  join public.engagement_batches b on b.id = bs.batch_id
  where bs.attendance_log_id = p_attendance_log_id;
  if not found then
    raise exception 'That student isn''t in a batch.' using errcode = 'P0002';
  end if;
  if v_batch.facilitator_id <> v_caller.id then
    raise exception 'Only the facilitator running this batch can record engagement.' using errcode = '42501';
  end if;
  if v_batch.status <> 'open' then
    raise exception 'This batch is finished, so its history can''t be changed.' using errcode = 'P0001';
  end if;

  select * into v_log from public.attendance_logs where id = p_attendance_log_id;

  -- "No" to the first question means the rest are skipped and logged as false.
  insert into public.engagement_logs
    (attendance_log_id, student_id, facilitator_id, campus_id, is_engaged, heard_gospel, accepted_jesus, wants_dgroup)
  values
    (v_log.id, v_log.student_id, v_caller.id, v_log.campus_id, p_is_engaged,
     p_is_engaged and p_heard_gospel, p_is_engaged and p_accepted_jesus, p_is_engaged and p_wants_dgroup)
  on conflict (attendance_log_id) do update set
    facilitator_id = excluded.facilitator_id,
    is_engaged = excluded.is_engaged,
    heard_gospel = excluded.heard_gospel,
    accepted_jesus = excluded.accepted_jesus,
    wants_dgroup = excluded.wants_dgroup;

  -- First save ends the engagement timer for this student; later edits don't move it.
  update public.attendance_logs set time_out = now() where id = v_log.id and time_out is null;

  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- finish_batch(): moves a completed batch to History. Refuses while any student still has no
-- engagement recorded. An empty batch is simply discarded.
-- ---------------------------------------------------------------------------
create or replace function public.finish_batch(p_batch_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller public.profiles%rowtype;
  v_batch public.engagement_batches%rowtype;
  v_total int;
  v_pending int;
begin
  select * into v_caller from public.profiles where id = auth.uid() and is_active;
  if not found or v_caller.role not in ('campus_head', 'facilitator') then
    raise exception 'Only a Campus Head or Facilitator can finish a batch.' using errcode = '42501';
  end if;

  select * into v_batch from public.engagement_batches where id = p_batch_id for update;
  if not found or v_batch.facilitator_id <> v_caller.id then
    raise exception 'That batch isn''t yours.' using errcode = '42501';
  end if;
  if v_batch.status <> 'open' then
    raise exception 'This batch is already finished.' using errcode = 'P0001';
  end if;

  select count(*) into v_total from public.batch_students where batch_id = p_batch_id;
  if v_total = 0 then
    delete from public.engagement_batches where id = p_batch_id;
    return jsonb_build_object('action', 'discarded', 'students', 0);
  end if;

  select count(*) into v_pending
  from public.batch_students bs
  left join public.engagement_logs e on e.attendance_log_id = bs.attendance_log_id
  where bs.batch_id = p_batch_id and e.id is null;
  if v_pending > 0 then
    raise exception 'Record engagement for % more student(s) before finishing this batch.', v_pending
      using errcode = 'P0001';
  end if;

  update public.engagement_batches set status = 'finished', finished_at = now() where id = p_batch_id;
  return jsonb_build_object('action', 'finished', 'students', v_total);
end;
$$;

-- ---------------------------------------------------------------------------
-- Backfill: attendance recorded before batches existed becomes one finished batch per
-- person per day, so History isn't empty. Runs only when there are no batches yet.
-- ---------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from public.engagement_batches) then
    insert into public.engagement_batches (campus_id, facilitator_id, batch_date, batch_number, status, started_at, finished_at)
    select a.campus_id, a.scanned_by, a.log_date, 1, 'finished', min(a.time_in), max(coalesce(a.time_out, a.time_in))
    from public.attendance_logs a
    group by a.campus_id, a.scanned_by, a.log_date;

    insert into public.batch_students (batch_id, student_id, attendance_log_id, campus_id, added_at)
    select b.id, a.student_id, a.id, a.campus_id, a.time_in
    from public.attendance_logs a
    join public.engagement_batches b
      on b.facilitator_id = a.scanned_by and b.batch_date = a.log_date and b.campus_id = a.campus_id;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Function permissions
-- ---------------------------------------------------------------------------
revoke execute on function public.start_batch() from public, anon;
revoke execute on function public.add_student_to_batch(uuid, uuid, text) from public, anon;
revoke execute on function public.save_engagement(uuid, boolean, boolean, boolean, boolean) from public, anon;
revoke execute on function public.finish_batch(uuid) from public, anon;
grant execute on function public.start_batch() to authenticated;
grant execute on function public.add_student_to_batch(uuid, uuid, text) to authenticated;
grant execute on function public.save_engagement(uuid, boolean, boolean, boolean, boolean) to authenticated;
grant execute on function public.finish_batch(uuid) to authenticated;

-- >>>>>>>>>> 0006_notifications.sql <<<<<<<<<<
-- Elevate Campus Hub — 0006 in-app notifications
--
-- Every notification belongs to ONE person, carries the app path to open when it is clicked (`link`),
-- and is created by the database itself (triggers), so it works no matter which screen caused the event.
-- Repeated events from the same source (for example several chat messages from one person) collapse into
-- one unread notification with a counter instead of flooding the bell.

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references public.profiles (id) on delete cascade,
  campus_id uuid references public.campuses (id),
  type text not null check (type in ('chat', 'assignment', 'attendance', 'batch', 'engagement', 'invitation', 'system')),
  title text not null,
  body text,
  -- App-relative path (never a full URL), so a notification can't send anyone off-site.
  link text not null,
  -- Collapses repeats while unread, for example "chat:<sender id>".
  group_key text,
  count int not null default 1 check (count > 0),
  is_read boolean not null default false,
  created_at timestamptz not null default now(),
  constraint notifications_link_relative check (link like '/%' and link not like '//%')
);

create index notifications_recipient_idx on public.notifications (recipient_id, created_at desc);
create index notifications_unread_idx on public.notifications (recipient_id) where not is_read;
create unique index notifications_one_unread_per_group
  on public.notifications (recipient_id, group_key) where group_key is not null and not is_read;

-- ---------------------------------------------------------------------------
-- Row level security: you only ever see and update your own notifications
-- ---------------------------------------------------------------------------
alter table public.notifications enable row level security;

create policy notifications_select on public.notifications for select to authenticated
  using (recipient_id = auth.uid());

create policy notifications_mark_read on public.notifications for update to authenticated
  using (recipient_id = auth.uid())
  with check (recipient_id = auth.uid());

-- Only is_read can change from the app; nothing is created or deleted from the app.
revoke update on public.notifications from authenticated, anon;
grant update (is_read) on public.notifications to authenticated;
revoke insert, delete on public.notifications from authenticated, anon;

-- Live updates for the bell (RLS still applies to subscribers).
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'notifications'
     ) then
    alter publication supabase_realtime add table public.notifications;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- notify(): the one way a notification is created (not callable from the app)
-- ---------------------------------------------------------------------------
create or replace function public.notify(
  p_recipient uuid,
  p_type text,
  p_title text,
  p_body text,
  p_link text,
  p_group text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_campus uuid;
  v_previous int;
begin
  select campus_id into v_campus from public.profiles where id = p_recipient and is_active;
  if not found then
    return;
  end if;

  -- Replace the previous unread one from the same source with a fresh row (so listeners see an
  -- INSERT) and carry the counter forward.
  if p_group is not null then
    delete from public.notifications
    where recipient_id = p_recipient and group_key = p_group and not is_read
    returning count into v_previous;
  end if;

  insert into public.notifications (recipient_id, campus_id, type, title, body, link, group_key, count)
  values (p_recipient, v_campus, p_type, p_title, p_body, p_link, p_group, coalesce(v_previous, 0) + 1);
end;
$$;

create or replace function public.notify_campus_heads(
  p_campus uuid,
  p_except uuid,
  p_type text,
  p_title text,
  p_body text,
  p_link text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_head uuid;
begin
  for v_head in
    select id from public.profiles
    where role = 'campus_head' and campus_id = p_campus and is_active and id is distinct from p_except
  loop
    perform public.notify(v_head, p_type, p_title, p_body, p_link);
  end loop;
end;
$$;

revoke execute on function public.notify(uuid, text, text, text, text, text) from public, anon, authenticated;
revoke execute on function public.notify_campus_heads(uuid, uuid, text, text, text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Chat: tell the other person (opens that conversation)
-- ---------------------------------------------------------------------------
create or replace function public.trg_chat_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sender public.profiles%rowtype;
  v_receiver public.profiles%rowtype;
  v_link text;
begin
  select * into v_sender from public.profiles where id = new.sender_id;
  select * into v_receiver from public.profiles where id = new.receiver_id;
  v_link := case v_receiver.role
    when 'student' then '/student/chat'
    when 'facilitator' then '/facilitator/chat?with=' || new.sender_id::text
    else '/'
  end;
  perform public.notify(new.receiver_id, 'chat', 'New message from ' || v_sender.first_name, left(new.message, 140), v_link, 'chat:' || new.sender_id::text);
  return new;
end;
$$;

create trigger chat_messages_notify after insert on public.chat_messages
  for each row execute function public.trg_chat_notify();

-- ---------------------------------------------------------------------------
-- Assignments: student gets their facilitator; facilitator gets the student (unless they did it
-- themselves by adding the student to a batch); Campus Heads are warned about different-gender pairs
-- ---------------------------------------------------------------------------
create or replace function public.trg_assignment_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_facilitator public.profiles%rowtype;
  v_student public.profiles%rowtype;
  v_actor uuid := auth.uid();
begin
  if not new.is_active then
    return new;
  end if;

  select * into v_facilitator from public.profiles where id = new.facilitator_id;
  select * into v_student from public.profiles where id = new.student_id;

  perform public.notify(new.student_id, 'assignment', v_facilitator.first_name || ' is now your facilitator',
    'You can message them and see when they''re available.', '/student');

  if v_actor is distinct from new.facilitator_id then
    perform public.notify(new.facilitator_id, 'assignment', v_student.first_name || ' ' || v_student.last_name || ' was assigned to you',
      'They''re now one of your students.', '/facilitator/students');
  end if;

  if v_facilitator.gender is distinct from v_student.gender then
    perform public.notify_campus_heads(new.campus_id, v_actor, 'assignment', 'Different-gender assignment',
      v_student.first_name || ' ' || v_student.last_name || ' is assigned to ' || v_facilitator.first_name
        || ', so chat is off for them. Consider reassigning.', '/campus-head/students');
  end if;
  return new;
end;
$$;

create trigger facilitator_students_notify after insert on public.facilitator_students
  for each row execute function public.trg_assignment_notify();

-- ---------------------------------------------------------------------------
-- Batches: Campus Heads see when a facilitator starts and finishes
-- ---------------------------------------------------------------------------
create or replace function public.trg_batch_started_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_facilitator public.profiles%rowtype;
begin
  select * into v_facilitator from public.profiles where id = new.facilitator_id;
  perform public.notify_campus_heads(new.campus_id, new.facilitator_id, 'batch',
    v_facilitator.first_name || ' started Batch ' || new.batch_number, 'See who they''re with on Live.', '/campus-head/live');
  return new;
end;
$$;

create trigger engagement_batches_started_notify after insert on public.engagement_batches
  for each row execute function public.trg_batch_started_notify();

create or replace function public.trg_batch_finished_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_facilitator public.profiles%rowtype;
  v_total int;
  v_engaged int;
begin
  select * into v_facilitator from public.profiles where id = new.facilitator_id;
  select count(*), count(*) filter (where e.is_engaged) into v_total, v_engaged
  from public.batch_students bs
  left join public.engagement_logs e on e.attendance_log_id = bs.attendance_log_id
  where bs.batch_id = new.id;

  perform public.notify_campus_heads(new.campus_id, new.facilitator_id, 'batch',
    v_facilitator.first_name || ' finished Batch ' || new.batch_number,
    v_total || ' ' || case when v_total = 1 then 'student' else 'students' end || ' · ' || v_engaged || ' engaged',
    '/campus-head/history');
  return new;
end;
$$;

create trigger engagement_batches_finished_notify after update on public.engagement_batches
  for each row when (old.status = 'open' and new.status = 'finished')
  execute function public.trg_batch_finished_notify();

-- A student is told when they are checked in (added to a batch)
create or replace function public.trg_checked_in_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_facilitator public.profiles%rowtype;
begin
  select p.* into v_facilitator
  from public.engagement_batches b join public.profiles p on p.id = b.facilitator_id
  where b.id = new.batch_id;
  perform public.notify(new.student_id, 'attendance', 'You''re checked in',
    v_facilitator.first_name || ' marked you present today.', '/student/attendance');
  return new;
end;
$$;

create trigger batch_students_notify after insert on public.batch_students
  for each row execute function public.trg_checked_in_notify();

-- ---------------------------------------------------------------------------
-- Engagement milestones worth a Campus Head's attention
-- ---------------------------------------------------------------------------
create or replace function public.trg_engagement_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_student public.profiles%rowtype;
  v_recorder public.profiles%rowtype;
  v_name text;
begin
  select * into v_student from public.profiles where id = new.student_id;
  select * into v_recorder from public.profiles where id = new.facilitator_id;
  v_name := v_student.first_name || ' ' || v_student.last_name;

  if new.accepted_jesus and (tg_op = 'INSERT' or not old.accepted_jesus) then
    perform public.notify_campus_heads(new.campus_id, new.facilitator_id, 'engagement',
      v_name || ' accepted Jesus', 'Recorded by ' || v_recorder.first_name || '.', '/campus-head/history');
  end if;
  if new.wants_dgroup and (tg_op = 'INSERT' or not old.wants_dgroup) then
    perform public.notify_campus_heads(new.campus_id, new.facilitator_id, 'engagement',
      v_name || ' wants to join a D-Group', 'Recorded by ' || v_recorder.first_name || '.', '/campus-head/history');
  end if;
  return new;
end;
$$;

create trigger engagement_logs_notify after insert or update on public.engagement_logs
  for each row execute function public.trg_engagement_notify();

-- ---------------------------------------------------------------------------
-- Invitations: tell the Campus Head (or Super Admin) when someone finishes setting up
-- ---------------------------------------------------------------------------
create or replace function public.trg_invitation_accepted_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := new.first_name || ' ' || new.last_name;
  v_admin uuid;
begin
  if new.role = 'student' then
    perform public.notify_campus_heads(new.campus_id, null, 'invitation', v_name || ' accepted the invitation',
      'They''ve set their password and can use their QR card.', '/campus-head/students');
  elsif new.role = 'facilitator' then
    perform public.notify_campus_heads(new.campus_id, null, 'invitation', v_name || ' joined as a facilitator',
      'They''ve accepted the invitation.', '/campus-head/facilitators');
  elsif new.role = 'campus_head' then
    for v_admin in select id from public.profiles where role = 'super_admin' and is_active loop
      perform public.notify(v_admin, 'invitation', v_name || ' accepted the Campus Head invitation', null, '/admin/users');
    end loop;
  end if;
  return new;
end;
$$;

create trigger profiles_invitation_accepted_notify after update of invitation_accepted_at on public.profiles
  for each row when (old.invitation_accepted_at is null and new.invitation_accepted_at is not null)
  execute function public.trg_invitation_accepted_notify();

-- ---------------------------------------------------------------------------
-- System problems go to every Super Admin (opens the system logs)
-- ---------------------------------------------------------------------------
create or replace function public.trg_system_error_notify()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid;
begin
  for v_admin in select id from public.profiles where role = 'super_admin' and is_active loop
    perform public.notify(v_admin, 'system', 'System problem: ' || replace(new.event, '_', ' '),
      left(coalesce(new.detail ->> 'error', new.detail::text, ''), 160), '/admin/logs');
  end loop;
  return new;
end;
$$;

create trigger system_logs_error_notify after insert on public.system_logs
  for each row when (new.level = 'error')
  execute function public.trg_system_error_notify();

-- >>>>>>>>>> 0007_privacy_consent.sql <<<<<<<<<<
-- Elevate Campus Hub — 0007 data privacy consent records
--
-- Two separate facts are recorded (Data Privacy Act of 2012, RA 10173: consent should be provable):
--   1. data_consent_*      — the person was informed and agreed when their account was REGISTERED.
--                            Captured by the facilitator / Campus Head / Super Admin who entered their details
--                            (data_consent_by). Required before an account can be created.
--   2. privacy_accepted_*  — the person accepted the notice THEMSELVES when they set up (or later re-confirmed)
--                            their account. Required again whenever the notice version changes.
--
-- No backfill: existing accounts have not accepted anything yet, so they will be asked once at their next sign-in.

alter table public.profiles
  add column data_consent_at timestamptz,
  add column data_consent_version text,
  add column data_consent_by uuid references public.profiles (id) on delete set null,
  add column privacy_accepted_at timestamptz,
  add column privacy_accepted_version text;

comment on column public.profiles.data_consent_at is 'When consent to collect/use this person''s data was recorded at registration.';
comment on column public.profiles.data_consent_by is 'Who recorded that consent on the person''s behalf (null when they did it themselves).';
comment on column public.profiles.privacy_accepted_version is 'Version of the Data Privacy Notice the person last accepted themselves (see src/lib/privacy.ts).';

-- >>>>>>>>>> 0008_form_report_and_attendance_sheet.sql <<<<<<<<<<
-- Elevate Campus Hub — 0008 Google Form report fields + attendance sheet helpers
--
-- 1. The ministry's "Elevate Engagement Report" Google Form asks for a "School/Location" that the system did not have:
--      campuses.report_location   default School/Location text for that campus
--      campuses.google_form_url   the campus's Google Form link (the app reads the form's fields from it and submits)
--      daily_reports.location     School/Location for one specific report (defaults to the campus value, editable)
-- 2. Two read-only functions that feed the Campus Head's attendance sheet (one row per student, not one per visit,
--    so a big campus stays under the API's 1000-row page limit).

alter table public.campuses
  add column google_form_url text,
  add column report_location text;

alter table public.daily_reports
  add column location text;

-- Which days each student attended within a date range. SECURITY INVOKER: RLS limits it to the viewer's campus.
create or replace function public.attendance_dates_by_student(p_campus_id uuid, p_from date, p_to date)
returns table (student_id uuid, dates date[])
language sql
stable
as $$
  select a.student_id, array_agg(distinct a.log_date order by a.log_date)
  from public.attendance_logs a
  where a.campus_id = p_campus_id and a.log_date between p_from and p_to
  group by a.student_id
$$;

-- The days the campus actually met (at least one student was recorded), oldest first.
create or replace function public.attendance_session_dates(p_campus_id uuid, p_from date, p_to date)
returns setof date
language sql
stable
as $$
  select distinct a.log_date
  from public.attendance_logs a
  where a.campus_id = p_campus_id and a.log_date between p_from and p_to
  order by 1
$$;

-- >>>>>>>>>> 0009_saved_google_forms.sql <<<<<<<<<<
-- Elevate Campus Hub — 0009 saved Google Forms
--
-- A campus can save several Google Forms (for example the weekly engagement report and a separate event report)
-- and the Campus Head picks which one to send a day's report to. This replaces the single campuses.google_form_url
-- from 0008: any link already stored there is moved into the new table first.

create table public.campus_google_forms (
  id uuid primary key default gen_random_uuid(),
  campus_id uuid not null references public.campuses (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  -- Always the normalised ".../forms/d/e/<id>/viewform" address (the app builds it), never a free-form URL.
  url text not null check (url like 'https://docs.google.com/forms/d/e/%'),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint campus_google_forms_unique_url unique (campus_id, url)
);

create index campus_google_forms_campus_idx on public.campus_google_forms (campus_id);

-- Only the campus's own Campus Head (and the Super Admin, read-only) can see or change a campus's forms.
alter table public.campus_google_forms enable row level security;

create policy campus_google_forms_select on public.campus_google_forms for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  );

create policy campus_google_forms_campus_head_write on public.campus_google_forms for all to authenticated
  using (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  with check (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id());

-- Keep whatever link a campus already had (0008 stored one per campus).
insert into public.campus_google_forms (campus_id, name, url)
select id, 'Google Form', google_form_url
from public.campuses
where google_form_url like 'https://docs.google.com/forms/d/e/%'
on conflict do nothing;

alter table public.campuses drop column google_form_url;

-- >>>>>>>>>> 0010_students_see_facilitator_name_only.sql <<<<<<<<<<
-- Elevate Campus Hub — 0010 students see their facilitator's name only
--
-- Until now a student could read the COMPLETE profile row of their assigned facilitator: email, phone, birthday,
-- church, religion and more, not just what the "Your facilitator" card showed. Hiding fields in the page isn't
-- enough (anyone signed in can query the API directly), so the database stops handing them out.
--
-- What students actually need is the facilitator's name (the card and the chat header) and gender (to tell whether
-- chat is allowed). `my_facilitator()` returns exactly that and nothing else. Chat itself is unaffected: the
-- same-gender rule runs inside `can_chat()`, which is SECURITY DEFINER and never needed the student to read the row.

-- Same policy as before, minus the last branch ("A student sees their assigned facilitator").
drop policy profiles_select on public.profiles;

create policy profiles_select on public.profiles for select to authenticated
  using (
    id = auth.uid()
    or public.auth_role() = 'super_admin'
    -- Campus Head sees everyone in the campus; facilitators see the campus's students.
    or (
      campus_id = public.auth_campus_id()
      and (
        public.auth_role() = 'campus_head'
        or (public.auth_role() = 'facilitator' and role = 'student')
      )
    )
  );

-- The signed-in student's assigned facilitator: id, name and gender only. Empty for anyone without one.
create or replace function public.my_facilitator()
returns table (id uuid, first_name text, last_name text, gender text)
language sql
stable
security definer
set search_path = public
as $$
  select f.id, f.first_name, f.last_name, f.gender
  from public.facilitator_students fs
  join public.profiles f on f.id = fs.facilitator_id
  where fs.student_id = auth.uid() and fs.is_active
$$;

revoke execute on function public.my_facilitator() from public, anon;
grant execute on function public.my_facilitator() to authenticated;

-- >>>>>>>>>> 0011_programs_per_campus_and_course.sql <<<<<<<<<<
-- Elevate Campus Hub — 0011 programs belong to a campus; students can have a typed course
--
-- The four programs (BSIT, BSED, BSA, BSBA) were "global" (campus_id null) and so were offered to every campus.
-- They are GRC's courses, so they now belong to GRC. A campus that has no programs of its own lets students TYPE
-- their course instead of picking from a list, which is what `profiles.course` holds.

update public.programs
set campus_id = (select id from public.campuses where code = 'GRC')
where campus_id is null
  and exists (select 1 from public.campuses where code = 'GRC');

-- Free-text course, used when the student's campus has no program list. (A student has either program_id or course.)
alter table public.profiles
  add column course text
  check (course is null or char_length(btrim(course)) between 1 and 80);

-- >>>>>>>>>> 0012_admin_move_user.sql <<<<<<<<<<
-- Elevate Campus Hub — 0012 move a person to another campus / change their role (Super Admin)
--
-- One atomic step for the sensitive part of editing a user: changing their campus and/or role. It
--   * refuses Super Admins, students becoming staff (or the reverse), and inactive/unknown campuses,
--   * refuses while the person has an open batch (they must finish it first),
--   * ends their active facilitator<->student assignments, because those only make sense inside one campus
--     and with the same role, and
--   * then changes the role and campus.
-- Nothing else about the person changes, and their history stays with the campus it happened in.
--
-- Only the server (service-role key) may call it, after checking that the caller is a Super Admin.

create or replace function public.admin_move_user(p_user uuid, p_role text, p_campus uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v public.profiles%rowtype;
  v_ended int := 0;
begin
  select * into v from public.profiles where id = p_user for update;
  if not found then raise exception 'That person could not be found.'; end if;

  if v.role = 'super_admin' then
    raise exception 'A Super Admin''s role and campus can''t be changed here.';
  end if;
  if p_role not in ('campus_head', 'facilitator', 'student') then
    raise exception 'Pick Campus Head, Facilitator or Student.';
  end if;
  if (v.role = 'student') <> (p_role = 'student') then
    raise exception 'A student can''t become staff (or the other way round). Create a new account instead.';
  end if;
  if not exists (select 1 from public.campuses where id = p_campus and is_active) then
    raise exception 'Pick an active campus.';
  end if;
  if p_role in ('facilitator', 'student') and v.gender is null then
    raise exception 'Set their gender first: it decides who they can chat with.';
  end if;

  if v.role = p_role and v.campus_id = p_campus then
    return jsonb_build_object('changed', false, 'ended_assignments', 0);
  end if;

  if exists (select 1 from public.engagement_batches where facilitator_id = p_user and status = 'open') then
    raise exception '% has an open batch. Finish it first, then move them.', v.first_name;
  end if;
  if exists (
    select 1
    from public.batch_students bs
    join public.engagement_batches b on b.id = bs.batch_id
    where bs.student_id = p_user and b.status = 'open'
  ) then
    raise exception '% is in a batch that is still open. Finish the batch first, then move them.', v.first_name;
  end if;

  update public.facilitator_students
  set is_active = false
  where is_active and (facilitator_id = p_user or student_id = p_user);
  get diagnostics v_ended = row_count;

  update public.profiles set role = p_role, campus_id = p_campus where id = p_user;

  return jsonb_build_object('changed', true, 'ended_assignments', v_ended);
end;
$$;

revoke execute on function public.admin_move_user(uuid, text, uuid) from public, anon, authenticated;
grant execute on function public.admin_move_user(uuid, text, uuid) to service_role;

-- >>>>>>>>>> 0013_facilitators_work_at_several_campuses.sql <<<<<<<<<<
-- Elevate Campus Hub — 0013 facilitators can work at several campuses
--
-- A facilitator is not tied to one school: they also go to others, each of which has its own Campus Head. So a
-- facilitator can work at several campuses. Campus Heads and students still belong to exactly one.
--
-- How it fits with everything that already works:
--   * profiles.campus_id stays "the campus I am working at right now". Every batch, attendance, row-level-security
--     rule and page already reads it, so they keep working unchanged, for whichever campus the facilitator is at.
--   * profile_campuses lists the OTHER campuses a facilitator also works at. A facilitator can work at their current
--     campus plus those, and switches between them with switch_my_campus() (the Super Admin sets the list).
--   * A Campus Head sees the facilitators who work at their campus even while those are set to another one, and a
--     facilitator keeps seeing (and can chat with) the students assigned to them at any of their campuses.

create table public.profile_campuses (
  profile_id uuid not null references public.profiles (id) on delete cascade,
  campus_id uuid not null references public.campuses (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (profile_id, campus_id)
);

create index profile_campuses_campus_idx on public.profile_campuses (campus_id);

alter table public.profile_campuses enable row level security;

-- You see your own list; the Super Admin sees all; a Campus Head sees who is listed for their campus.
create policy profile_campuses_select on public.profile_campuses for select to authenticated
  using (
    profile_id = auth.uid()
    or public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
  );

-- Nothing is written from the app directly: only admin_move_user() and switch_my_campus() below change it.
revoke insert, update, delete on public.profile_campuses from authenticated, anon;

-- Does this person work at this campus (it is their current one, or one of their extra ones)?
create or replace function public.works_at(p_user uuid, p_campus uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.profiles p where p.id = p_user and p.campus_id = p_campus)
      or exists (select 1 from public.profile_campuses pc where pc.profile_id = p_user and pc.campus_id = p_campus)
$$;

revoke execute on function public.works_at(uuid, uuid) from public, anon;
grant execute on function public.works_at(uuid, uuid) to authenticated;

-- Same-gender chat: unchanged, except the facilitator only needs to WORK AT the student's campus, not be set to it.
create or replace function public.can_chat(p_a uuid, p_b uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.facilitator_students fs
    join public.profiles f on f.id = fs.facilitator_id
    join public.profiles s on s.id = fs.student_id
    where fs.is_active
      and f.is_active and s.is_active
      and f.role = 'facilitator' and s.role = 'student'
      and f.gender is not null and f.gender = s.gender
      and public.works_at(f.id, s.campus_id)
      and ((fs.facilitator_id = p_a and fs.student_id = p_b)
        or (fs.facilitator_id = p_b and fs.student_id = p_a))
  )
$$;

-- profiles: the same rules as 0010, plus two things that follow from facilitators working at several campuses.
drop policy profiles_select on public.profiles;

create policy profiles_select on public.profiles for select to authenticated
  using (
    id = auth.uid()
    or public.auth_role() = 'super_admin'
    -- Campus Head sees everyone in the campus; facilitators see the campus's students.
    or (
      campus_id = public.auth_campus_id()
      and (
        public.auth_role() = 'campus_head'
        or (public.auth_role() = 'facilitator' and role = 'student')
      )
    )
    -- A Campus Head also sees the facilitators who work at their campus while currently set to another one.
    or (
      public.auth_role() = 'campus_head'
      and role = 'facilitator'
      and exists (
        select 1 from public.profile_campuses pc
        where pc.profile_id = profiles.id and pc.campus_id = public.auth_campus_id()
      )
    )
    -- A facilitator sees the students assigned to them, at whichever of their campuses the student is.
    or (
      public.auth_role() = 'facilitator'
      and role = 'student'
      and id in (
        select fs.student_id from public.facilitator_students fs
        where fs.facilitator_id = auth.uid() and fs.is_active
      )
    )
  );

-- A Campus Head sees the weekly availability of everyone who works at their campus.
drop policy availability_select on public.facilitator_availability;

create policy availability_select on public.facilitator_availability for select to authenticated
  using (
    facilitator_id = auth.uid()
    or public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and public.works_at(facilitator_id, public.auth_campus_id()))
    or facilitator_id in (
      select fs.facilitator_id from public.facilitator_students fs
      where fs.student_id = auth.uid() and fs.is_active
    )
  );

-- ---------------------------------------------------------------------------
-- The campuses the signed-in facilitator works at (for the switcher in the header)
-- ---------------------------------------------------------------------------
create or replace function public.my_campuses()
returns table (id uuid, code text, name text, is_current boolean)
language sql
stable
security definer
set search_path = public
as $$
  select c.id, c.code, c.name, (c.id = p.campus_id) as is_current
  from public.profiles p
  join public.campuses c
    on c.id = p.campus_id
    or c.id in (select pc.campus_id from public.profile_campuses pc where pc.profile_id = p.id)
  where p.id = auth.uid() and p.role = 'facilitator' and p.is_active and c.is_active
  order by is_current desc, c.code
$$;

revoke execute on function public.my_campuses() from public, anon;
grant execute on function public.my_campuses() to authenticated;

-- ---------------------------------------------------------------------------
-- A facilitator switches which of their campuses they are working at
-- ---------------------------------------------------------------------------
create or replace function public.switch_my_campus(p_campus uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v public.profiles%rowtype;
begin
  select * into v from public.profiles where id = auth.uid() and is_active for update;
  if not found or v.role <> 'facilitator' then
    raise exception 'Only facilitators can switch campus.';
  end if;

  if v.campus_id = p_campus then
    return jsonb_build_object('changed', false);
  end if;
  if not exists (
    select 1
    from public.profile_campuses pc
    join public.campuses c on c.id = pc.campus_id
    where pc.profile_id = v.id and pc.campus_id = p_campus and c.is_active
  ) then
    raise exception 'You don''t work at that campus.';
  end if;
  -- A batch belongs to the campus it was started at, so it has to be finished before moving on.
  if exists (select 1 from public.engagement_batches where facilitator_id = v.id and status = 'open') then
    raise exception 'Finish your open batch first, then switch campus.';
  end if;

  update public.profiles set campus_id = p_campus where id = v.id;
  -- Keep the list "every campus except the current one".
  delete from public.profile_campuses where profile_id = v.id and campus_id = p_campus;
  insert into public.profile_campuses (profile_id, campus_id) values (v.id, v.campus_id) on conflict do nothing;

  return jsonb_build_object('changed', true);
end;
$$;

revoke execute on function public.switch_my_campus(uuid) from public, anon;
grant execute on function public.switch_my_campus(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Super Admin: move someone / change their role / set the campuses a facilitator works at
-- (replaces the 3-argument version from 0012; callers that pass three arguments keep working)
-- ---------------------------------------------------------------------------
drop function public.admin_move_user(uuid, text, uuid);

create function public.admin_move_user(p_user uuid, p_role text, p_campus uuid, p_extra uuid[] default '{}')
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v public.profiles%rowtype;
  v_extras uuid[];
  v_old uuid[];
  v_new uuid[];
  v_removed uuid[];
  v_ended int := 0;
begin
  select * into v from public.profiles where id = p_user for update;
  if not found then raise exception 'That person could not be found.'; end if;

  if v.role = 'super_admin' then
    raise exception 'A Super Admin''s role and campus can''t be changed here.';
  end if;
  if p_role not in ('campus_head', 'facilitator', 'student') then
    raise exception 'Pick Campus Head, Facilitator or Student.';
  end if;
  if (v.role = 'student') <> (p_role = 'student') then
    raise exception 'A student can''t become staff (or the other way round). Create a new account instead.';
  end if;
  if not exists (select 1 from public.campuses where id = p_campus and is_active) then
    raise exception 'Pick an active campus.';
  end if;
  if p_role in ('facilitator', 'student') and v.gender is null then
    raise exception 'Set their gender first: it decides who they can chat with.';
  end if;

  -- Only facilitators work at several campuses; for everyone else the extra list is ignored.
  v_extras := case
    when p_role = 'facilitator'
      then array(select distinct e from unnest(coalesce(p_extra, '{}'::uuid[])) e where e is not null and e <> p_campus)
    else '{}'::uuid[]
  end;
  if exists (select 1 from unnest(v_extras) e where not exists (select 1 from public.campuses c where c.id = e and c.is_active)) then
    raise exception 'Every campus must be an active campus.';
  end if;

  v_old := array(
    select distinct c from (
      select v.campus_id as c
      union all
      select campus_id from public.profile_campuses where profile_id = p_user
    ) s where c is not null
  );
  v_new := array_append(v_extras, p_campus);
  v_removed := array(select o from unnest(v_old) o where not (o = any (v_new)));

  if v.role = p_role
     and v.campus_id is not distinct from p_campus
     and cardinality(v_removed) = 0
     and not exists (select 1 from unnest(v_new) n where not (n = any (v_old))) then
    return jsonb_build_object('changed', false, 'ended_assignments', 0);
  end if;

  -- Changing role, current campus, or dropping a campus needs their batches finished. Only ADDING a campus doesn't.
  if v.role <> p_role or v.campus_id is distinct from p_campus or cardinality(v_removed) > 0 then
    if exists (select 1 from public.engagement_batches where facilitator_id = p_user and status = 'open') then
      raise exception '% has an open batch. Finish it first, then move them.', v.first_name;
    end if;
    if exists (
      select 1
      from public.batch_students bs
      join public.engagement_batches b on b.id = bs.batch_id
      where bs.student_id = p_user and b.status = 'open'
    ) then
      raise exception '% is in a batch that is still open. Finish the batch first, then move them.', v.first_name;
    end if;
  end if;

  -- Assignments only make sense inside one campus and one role.
  if v.role <> p_role then
    update public.facilitator_students set is_active = false
    where is_active and (facilitator_id = p_user or student_id = p_user);
    get diagnostics v_ended = row_count;
  elsif v.role = 'student' then
    if v.campus_id is distinct from p_campus then
      update public.facilitator_students set is_active = false where is_active and student_id = p_user;
      get diagnostics v_ended = row_count;
    end if;
  else
    -- Staff keep working with the students of every campus they still work at; only those of a campus dropped end.
    update public.facilitator_students set is_active = false
    where is_active and facilitator_id = p_user and campus_id = any (v_removed);
    get diagnostics v_ended = row_count;
  end if;

  update public.profiles set role = p_role, campus_id = p_campus where id = p_user;
  delete from public.profile_campuses where profile_id = p_user;
  insert into public.profile_campuses (profile_id, campus_id) select p_user, e from unnest(v_extras) e;

  return jsonb_build_object('changed', true, 'ended_assignments', v_ended, 'campuses', cardinality(v_new));
end;
$$;

revoke execute on function public.admin_move_user(uuid, text, uuid, uuid[]) from public, anon, authenticated;
grant execute on function public.admin_move_user(uuid, text, uuid, uuid[]) to service_role;

-- >>>>>>>>>> 0014_email_only_invitations.sql <<<<<<<<<<
-- Elevate Campus Hub — 0014 invite a Campus Head or facilitator with just their email
--
-- Until now whoever added a Campus Head or facilitator had to type their name, gender, phone and more. Now only the
-- email is needed: the person gets an invitation with a 6-digit code, registers, and fills in their own details.
--
-- Until they do, we only know their email, so the profile is marked `details_complete = false`. A facilitator's
-- gender is normally required (it decides who they can chat with); the rule now waits until they have registered.

alter table public.profiles
  add column details_complete boolean not null default true;

alter table public.profiles drop constraint profiles_gender_required;

alter table public.profiles
  add constraint profiles_gender_required
  check (role not in ('student', 'facilitator') or gender is not null or not details_complete);

-- >>>>>>>>>> 0015_student_roster.sql <<<<<<<<<<
-- Elevate Campus Hub — 0015 campus student roster
--
-- A campus can already have a list of its students (an attendance sheet) before any of them has an account. The roster
-- holds those names. When a student is registered with a matching name, the roster entry is linked to the new account
-- (`claimed_by`), so the campus can see who still hasn't registered and nobody is entered twice.
--
-- Names are compared by `name_key`: the words of the name, lower-cased, without accents, initials or suffixes, sorted
-- (so "Abordo, Irish Nicole" and "Irish Nicole Abordo" are the same). See src/lib/roster.ts.
--
-- The roster is filled by the import script and linked by the server (service role); the app only reads it.

create table public.roster_students (
  id uuid primary key default gen_random_uuid(),
  campus_id uuid not null references public.campuses(id) on delete cascade,
  full_name text not null check (char_length(full_name) between 1 and 160),
  name_key text not null check (char_length(name_key) between 1 and 200),
  gender text check (gender in ('male', 'female')),
  year_level int check (year_level between 1 and 10),
  course text check (char_length(course) <= 80),
  -- The account this name was matched to. Deleting the account frees the name again.
  claimed_by uuid references public.profiles(id) on delete set null,
  claimed_at timestamptz,
  created_at timestamptz not null default now()
);

-- One entry per person per campus; an account can be linked to only one roster name.
create unique index roster_students_campus_key_idx on public.roster_students (campus_id, name_key);
create unique index roster_students_claimed_by_idx on public.roster_students (claimed_by) where claimed_by is not null;

alter table public.roster_students enable row level security;

-- The Super Admin sees every roster; a Campus Head and the facilitators who work at the campus see theirs.
create policy roster_students_select on public.roster_students for select to authenticated
  using (
    public.auth_role() = 'super_admin'
    or (public.auth_role() = 'campus_head' and campus_id = public.auth_campus_id())
    or (public.auth_role() = 'facilitator' and public.works_at(auth.uid(), campus_id))
  );

-- Nothing is written from the app directly (the server uses the service role).
revoke insert, update, delete on public.roster_students from authenticated, anon;
